/**
 * Control panel for the WebGL floor visualizer (visualizer-build-spec Part
 * 4). Renders: finish-system-aware blend chips / base coat swatches /
 * density & size controls / metallic colorway chips / custom blend
 * builder — all sharing the one FloorVisualizer canvas instance, per the
 * "Finish system -> visualizer mode mapping" table.
 *
 * Every chip thumbnail (blend and metallic) is generated by the SAME
 * procedural renderers the live canvas uses, at 128px, per spec: "never
 * ship static swatch images — one renderer, guaranteed visual consistency
 * between chip and floor."
 */
import { renderFlakeTexture, defaultSeedFor } from '/lib/flake-texture-renderer.js';
import { resolveRenderComponents, FLAKE_SOLID_COLORS, getBlendRecipe } from '/lib/flake-recipes.js';
import { METALLIC_COLORWAYS, renderMetallicSwatchTexture } from '/lib/metallic-swatches.js';
import { track } from './analytics.js';

const CHIP_SIZE = 128;

/** Spec Part 4: "Group chips: Grays & Neutrals / Earth Tones / Bold &
 * Custom." Covers all 20 blends lib/flake-recipes.js now carries — the
 * spec's own Part 1.2 verified seed set (13) plus the Part 1.3 scrape
 * task's 7 additional verified blends (catalog completion pass). Grouped
 * by the components' dominant tone. */
const BLEND_GROUPS = [
  { label: 'Grays & Neutrals', blendIds: ['domino', 'gravel', 'wombat', 'nightfall', 'raven', 'feather-gray', 'blizzard', 'water-lily', 'weathered-gray'] },
  { label: 'Earth Tones', blendIds: ['cabin-fever', 'coyote', 'creekbed', 'shoreline', 'outback'] },
  { label: 'Bold & Custom', blendIds: ['tidal-wave', 'orbit', 'galaxy', 'hog', 'rapids', 'rebel'] },
];

const BLEND_LABELS = {
  domino: 'Domino', gravel: 'Gravel', 'tidal-wave': 'Tidal Wave',
  'cabin-fever': 'Cabin Fever', wombat: 'Wombat', coyote: 'Coyote',
  nightfall: 'Nightfall', raven: 'Raven', creekbed: 'Creekbed',
  shoreline: 'Shoreline', outback: 'Outback', orbit: 'Orbit', galaxy: 'Galaxy',
  'feather-gray': 'Feather Gray', hog: 'Hog', blizzard: 'Blizzard',
  'water-lily': 'Water Lily', rapids: 'Rapids', rebel: 'Rebel', 'weathered-gray': 'Weathered Gray',
};

/** Standard professional base coat palette — constrained on purpose (spec
 * Part 4: "remove/do not build any free hex or custom color picker for
 * base coat... a free hex picker generates unquotable leads"). */
export const BASE_COAT_PALETTE = [
  { id: 'light-gray', label: 'Light Gray', hex: '#B8BEC6' },
  { id: 'medium-gray', label: 'Medium Gray', hex: '#8A8F98' },
  { id: 'dark-gray', label: 'Dark Gray', hex: '#6B7078' },
  { id: 'charcoal', label: 'Charcoal', hex: '#4A4F54' },
  { id: 'tan', label: 'Tan', hex: '#C4A882' },
  { id: 'beige', label: 'Beige', hex: '#D9CBAE' },
  { id: 'white', label: 'White', hex: '#F4F3EF' },
  { id: 'black', label: 'Black', hex: '#1C1E22' },
  { id: 'tile-red', label: 'Tile Red', hex: '#8C3B32' },
  { id: 'dark-blue', label: 'Dark Blue', hex: '#26385C' },
];

export function findBaseCoat(id) {
  return BASE_COAT_PALETTE.find((c) => c.id === id) || BASE_COAT_PALETTE[0];
}

const DENSITY_PRESETS = [
  { label: 'Full Broadcast', value: 1 },
  { label: 'Heavy', value: 0.75 },
  { label: 'Medium Broadcast', value: 0.5 },
  { label: 'Light Scatter', value: 0.25 },
];

const FLAKE_SIZES = [
  { label: '1/16"', value: 0.0625 },
  { label: '1/8"', value: 0.125 },
  { label: '1/4"', value: 0.25 },
  { label: '1/2"', value: 0.5 },
  { label: '1"', value: 1 },
];

const thumbCache = new Map();
function offscreen(size) {
  const c = document.createElement('canvas');
  c.width = size;
  c.height = size;
  return c;
}

function blendThumb(blendId, baseCoatHex) {
  const key = `blend:${blendId}:${baseCoatHex}`;
  if (thumbCache.has(key)) return thumbCache.get(key);
  const canvas = offscreen(CHIP_SIZE);
  const ctx = canvas.getContext('2d');
  const components = resolveRenderComponents({ blendId });
  renderFlakeTexture(
    { size: CHIP_SIZE, baseCoatHex, components, density: 1, flakeSizeIn: 0.25, seed: defaultSeedFor(1, 0.25) },
    ctx,
  );
  const url = canvas.toDataURL('image/png');
  thumbCache.set(key, url);
  return url;
}

function customThumb(components, baseCoatHex) {
  const canvas = offscreen(CHIP_SIZE);
  const ctx = canvas.getContext('2d');
  renderFlakeTexture(
    {
      size: CHIP_SIZE,
      baseCoatHex,
      components: resolveRenderComponents({ customComponents: components }),
      density: 1,
      flakeSizeIn: 0.25,
      seed: defaultSeedFor(1, 0.25),
    },
    ctx,
  );
  return canvas.toDataURL('image/png');
}

function metallicThumb(colorwayId) {
  const key = `metallic:${colorwayId}`;
  if (thumbCache.has(key)) return thumbCache.get(key);
  const canvas = offscreen(CHIP_SIZE);
  const ctx = canvas.getContext('2d');
  renderMetallicSwatchTexture({ size: CHIP_SIZE, colorwayId }, ctx);
  const url = canvas.toDataURL('image/png');
  thumbCache.set(key, url);
  return url;
}

function colorOptionsHtml(selectedCode) {
  return FLAKE_SOLID_COLORS.map(
    (c) => `<option value="${c.code}"${c.code === selectedCode ? ' selected' : ''}>${c.name}</option>`,
  ).join('');
}

/**
 * @param {HTMLElement} root
 * @param {{finish:string, baseCoatId:string, blendId:string, customComponents:Array|null, density:number, flakeSizeIn:number, metallicId:string}} state
 * @param {{onSpecChange:(partial:object)=>void, onFinishChange:(finish:string)=>void}} callbacks
 */
export function renderVisualizerControls(root, state, callbacks) {
  const s = { ...state };
  const { onSpecChange, onFinishChange } = callbacks;

  root.innerHTML = `
    <div class="viz-controls">
      <div class="viz-finish-tabs" data-role="finishTabs">
        <button type="button" data-finish="flake">Flake</button>
        <button type="button" data-finish="solid">Solid Color</button>
        <button type="button" data-finish="metallic">Metallic</button>
      </div>

      <div data-role="flakeSection">
        <p class="viz-label">Flake blend</p>
        <div data-role="blendGroups"></div>
        <div class="viz-custom-builder" data-role="customBuilder" hidden>
          <div class="viz-custom-rows" data-role="customRows"></div>
          <button type="button" class="btn btn-o btn-sm" data-role="addComponent">+ Add color</button>
          <p class="viz-hint" data-role="customTotal"></p>
        </div>
        <p class="viz-label">Coverage <span class="viz-value" data-role="densityValue"></span></p>
        <div class="viz-seg" data-role="densityPresets"></div>
        <input type="range" min="0" max="1" step="0.01" data-role="densitySlider">
        <p class="viz-label">Flake size</p>
        <div class="viz-seg" data-role="flakeSizeSeg"></div>
      </div>

      <div data-role="metallicSection" hidden>
        <p class="viz-label">Metallic colorway</p>
        <div class="viz-chip-row" data-role="metallicChips"></div>
      </div>

      <div data-role="baseCoatSection">
        <p class="viz-label">Base coat</p>
        <div class="viz-swatch-row" data-role="baseCoatSwatches"></div>
      </div>
    </div>`;

  const q = (sel) => root.querySelector(sel);

  function chipButton({ id, label, thumbUrl, on, dataAttr }) {
    return `<button type="button" class="viz-chip${on ? ' on' : ''}" data-${dataAttr}="${id}" title="${label}">
      <span class="viz-chip-swatch" style="background-image:url('${thumbUrl}')"></span>
      <span class="viz-chip-label">${label}</span>
    </button>`;
  }

  function renderBlendGroups() {
    const baseCoatHex = findBaseCoat(s.baseCoatId).hex;
    const groupsHtml = BLEND_GROUPS.map((group) => `
      <div class="viz-blend-group">
        <p class="viz-group-label">${group.label}</p>
        <div class="viz-chip-row">
          ${group.blendIds.map((id) => chipButton({
            id, label: BLEND_LABELS[id] || id, thumbUrl: blendThumb(id, baseCoatHex),
            on: s.blendId === id && !s.customComponents, dataAttr: 'blend',
          })).join('')}
        </div>
      </div>`).join('');

    const customOn = Boolean(s.customComponents);
    q('[data-role="blendGroups"]').innerHTML = `
      ${groupsHtml}
      <div class="viz-blend-group">
        <div class="viz-chip-row">
          <button type="button" class="viz-chip${customOn ? ' on' : ''}" data-custom-toggle="1" title="Custom blend">
            <span class="viz-chip-swatch" style="background-image:url('${customOn ? customThumb(s.customComponents, baseCoatHex) : blendThumb('gravel', baseCoatHex)}')"></span>
            <span class="viz-chip-label">Custom</span>
          </button>
        </div>
      </div>`;

    q('[data-role="blendGroups"]').querySelectorAll('[data-blend]').forEach((btn) => {
      btn.addEventListener('click', () => {
        s.blendId = btn.dataset.blend;
        s.customComponents = null;
        onSpecChange({ blendId: s.blendId, customComponents: null });
        track('blend_changed', { blendId: s.blendId });
        renderBlendGroups();
        q('[data-role="customBuilder"]').hidden = true;
      });
    });
    const customToggle = q('[data-custom-toggle]');
    if (customToggle) {
      customToggle.addEventListener('click', () => {
        if (!s.customComponents) {
          s.customComponents = getBlendRecipe(s.blendId)?.components?.map((c) => ({ ...c })) || [
            { colorCode: 'F1050', pct: 50 },
            { colorCode: 'F1820', pct: 50 },
          ];
          onSpecChange({ blendId: 'CUSTOM', customComponents: s.customComponents });
          track('blend_changed', { blendId: 'custom' });
        }
        renderBlendGroups();
        renderCustomRows();
        q('[data-role="customBuilder"]').hidden = false;
      });
    }
  }

  function customTotalPct() {
    return (s.customComponents || []).reduce((sum, c) => sum + (Number(c.pct) || 0), 0);
  }

  function renderCustomRows() {
    const rowsEl = q('[data-role="customRows"]');
    rowsEl.innerHTML = (s.customComponents || []).map((comp, i) => `
      <div class="viz-custom-row" data-i="${i}">
        <select data-field="code">${colorOptionsHtml(comp.colorCode)}</select>
        <input type="number" data-field="pct" min="1" max="100" value="${comp.pct}">
        <button type="button" data-field="remove" title="Remove" ${(s.customComponents.length <= 2) ? 'disabled' : ''}>&times;</button>
      </div>`).join('');

    rowsEl.querySelectorAll('.viz-custom-row').forEach((row) => {
      const i = Number(row.dataset.i);
      row.querySelector('[data-field="code"]').addEventListener('change', (e) => {
        s.customComponents[i].colorCode = e.target.value;
        emitCustomChange();
      });
      row.querySelector('[data-field="pct"]').addEventListener('input', (e) => {
        s.customComponents[i].pct = Number(e.target.value) || 0;
        emitCustomChange();
      });
      row.querySelector('[data-field="remove"]').addEventListener('click', () => {
        if (s.customComponents.length <= 2) return;
        s.customComponents.splice(i, 1);
        renderCustomRows();
        emitCustomChange();
      });
    });

    q('[data-role="customTotal"]').textContent = `Total: ${Math.round(customTotalPct())}% (auto-balances to 100%)`;
  }

  function emitCustomChange() {
    onSpecChange({ blendId: 'CUSTOM', customComponents: s.customComponents.map((c) => ({ ...c })) });
    track('blend_changed', { blendId: 'custom' });
    q('[data-role="customTotal"]').textContent = `Total: ${Math.round(customTotalPct())}% (auto-balances to 100%)`;
    renderBlendGroups();
  }

  q('[data-role="addComponent"]').addEventListener('click', () => {
    if (!s.customComponents) return;
    if (s.customComponents.length >= 8) return;
    const used = new Set(s.customComponents.map((c) => c.colorCode));
    const next = FLAKE_SOLID_COLORS.find((c) => !used.has(c.code)) || FLAKE_SOLID_COLORS[0];
    s.customComponents.push({ colorCode: next.code, pct: 10 });
    renderCustomRows();
    emitCustomChange();
  });

  function renderDensity() {
    q('[data-role="densityValue"]').textContent = `${Math.round(s.density * 100)}%`;
    q('[data-role="densitySlider"]').value = String(s.density);
    q('[data-role="densityPresets"]').innerHTML = DENSITY_PRESETS.map(
      (p) => `<button type="button" class="${Math.abs(s.density - p.value) < 0.01 ? 'on' : ''}" data-density="${p.value}">${p.label}</button>`,
    ).join('');
    q('[data-role="densityPresets"]').querySelectorAll('button').forEach((btn) => {
      btn.addEventListener('click', () => {
        s.density = Number(btn.dataset.density);
        onSpecChange({ density: s.density });
        track('density_changed', { density: s.density });
        renderDensity();
      });
    });
  }
  q('[data-role="densitySlider"]').addEventListener('input', (e) => {
    s.density = Number(e.target.value);
    onSpecChange({ density: s.density });
    renderDensity();
  });
  q('[data-role="densitySlider"]').addEventListener('change', () => {
    track('density_changed', { density: s.density });
  });

  function renderFlakeSize() {
    q('[data-role="flakeSizeSeg"]').innerHTML = FLAKE_SIZES.map(
      (fs) => `<button type="button" class="${s.flakeSizeIn === fs.value ? 'on' : ''}" data-size="${fs.value}">${fs.label}</button>`,
    ).join('');
    q('[data-role="flakeSizeSeg"]').querySelectorAll('button').forEach((btn) => {
      btn.addEventListener('click', () => {
        s.flakeSizeIn = Number(btn.dataset.size);
        onSpecChange({ flakeSizeIn: s.flakeSizeIn });
        renderFlakeSize();
      });
    });
  }

  function renderMetallicChips() {
    q('[data-role="metallicChips"]').innerHTML = METALLIC_COLORWAYS.map((c) =>
      chipButton({ id: c.id, label: c.label, thumbUrl: metallicThumb(c.id), on: s.metallicId === c.id, dataAttr: 'metallic' }),
    ).join('');
    q('[data-role="metallicChips"]').querySelectorAll('[data-metallic]').forEach((btn) => {
      btn.addEventListener('click', () => {
        s.metallicId = btn.dataset.metallic;
        onSpecChange({ metallicId: s.metallicId });
        track('blend_changed', { metallicId: s.metallicId });
        renderMetallicChips();
      });
    });
  }

  function renderBaseCoat() {
    q('[data-role="baseCoatSwatches"]').innerHTML = BASE_COAT_PALETTE.map(
      (c) => `<button type="button" class="viz-swatch${s.baseCoatId === c.id ? ' on' : ''}" style="background:${c.hex}" data-basecoat="${c.id}" title="${c.label}"></button>`,
    ).join('');
    q('[data-role="baseCoatSwatches"]').querySelectorAll('[data-basecoat]').forEach((btn) => {
      btn.addEventListener('click', () => {
        s.baseCoatId = btn.dataset.basecoat;
        onSpecChange({ baseCoatHex: findBaseCoat(s.baseCoatId).hex, baseCoatId: s.baseCoatId });
        track('basecoat_changed', { baseCoatId: s.baseCoatId });
        renderBaseCoat();
        renderBlendGroups();
      });
    });
  }

  function syncFinishSections() {
    q('[data-role="finishTabs"]').querySelectorAll('button').forEach((btn) => {
      btn.classList.toggle('on', btn.dataset.finish === s.finish);
    });
    q('[data-role="flakeSection"]').hidden = s.finish !== 'flake';
    q('[data-role="metallicSection"]').hidden = s.finish !== 'metallic';
    // Spec mapping table: solid color = base coat only, no flake controls.
    q('[data-role="baseCoatSection"]').hidden = s.finish === 'metallic';
  }

  q('[data-role="finishTabs"]').querySelectorAll('button').forEach((btn) => {
    btn.addEventListener('click', () => {
      s.finish = btn.dataset.finish;
      syncFinishSections();
      onFinishChange(s.finish);
    });
  });

  renderBlendGroups();
  renderCustomRows();
  renderDensity();
  renderFlakeSize();
  renderMetallicChips();
  renderBaseCoat();
  syncFinishSections();

  return {
    getState: () => ({ ...s }),
  };
}
